mapper.select:
SELECT c.id, c.class_name, c.teacher_id, c.room_number, c.create_time, c.update_time, c.is_deleted, t.name AS teacher_name, (SELECT COUNT(*) FROM student s WHERE s.class_id = c.id AND s.is_deleted = 0) AS student_count FROM `class` c LEFT JOIN teacher t ON c.teacher_id = t.id AND t.is_deleted = 0 WHERE c.is_deleted = 0
AND c.class_name LIKE CONCAT('%', #{className}, '%')
ORDER BY c.id DESC LIMIT #{offset}, #{pageSize}
